/* EDUVERSE service worker — precache shell + bank chunks. Generated by build-split.js. */
const CACHE = "eduverse-v1";
const PRECACHE = ["./","index.html","banks/pilot.js","banks/A.js","banks/B.js","banks/C.js","banks/D.js","banks/E.js","banks/dikdin.js","banks/sat.js","banks/simak.js","banks/ielts.js","banks/ielts_prompts.js"];
self.addEventListener("install", function(e){ e.waitUntil(caches.open(CACHE).then(function(c){ return c.addAll(PRECACHE); }).then(function(){ return self.skipWaiting(); })); });
self.addEventListener("activate", function(e){ e.waitUntil(caches.keys().then(function(keys){ return Promise.all(keys.filter(function(k){ return k !== CACHE; }).map(function(k){ return caches.delete(k); })); }).then(function(){ return self.clients.claim(); })); });
self.addEventListener("fetch", function(e){
  if(e.request.method !== "GET") return;
  const url = new URL(e.request.url);
  if(url.origin !== self.location.origin) return;
  const p = url.pathname;
  const precached = (p === "/" || p.endsWith("/index.html") || p.indexOf("/banks/") !== -1);
  if(!precached) return;
  e.respondWith(caches.match(e.request).then(function(cached){ if(cached) return cached; return fetch(e.request).then(function(res){ if(res && res.ok){ const copy = res.clone(); caches.open(CACHE).then(function(c){ c.put(e.request, copy); }); } return res; }); }));
});
